import com.sun.net.httpserver.*; import java.net.InetSocketAddress; import java.nio.charset.StandardCharsets;
public class SchoolRestApiDemo { public static void main(String[] args)throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress(8081),0);server.createContext("/students",exchange->{byte[] body="[{\"id\":\"ST01\",\"name\":\"Ada Okafor\"}]".getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");exchange.sendResponseHeaders(200,body.length);try(java.io.OutputStream out=exchange.getResponseBody()){out.write(body);}});server.start();System.out.println("GET endpoint: http://localhost:8081/students (press Ctrl+C to stop)");} }
